import type {PublicProjection,ProjectedBlock} from '../domain/projection';
import {PROJECTION_FIELDS} from '../domain/projection';
import {validatePublicPositions} from '../domain/exportPreparation';
import {parseStrictJson,jsonBytes,sha256} from '../storage/json';
import {SyncProtocolError} from './protocol';
export interface SharedSnapshot {id:string;projection:PublicProjection;contentHash:string;createdAt:string;accessExpiresAt:string|null;role:'owner'|'editor'|'reviewer'|'reader'}
const publicId=/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;
/** One approved projection serves text, search, figures, counts, links and assets. Author records are never accepted. */
export async function validateSharedSnapshot(input:unknown):Promise<SharedSnapshot>{
 const parsed=parseStrictJson(jsonBytes(input),'shared-snapshot.json') as SharedSnapshot;
 if(!parsed||Object.keys(parsed).some(k=>!['id','projection','contentHash','createdAt','accessExpiresAt','role'].includes(k))||typeof parsed.id!=='string'||!['owner','editor','reviewer','reader'].includes(parsed.role)||typeof parsed.createdAt!=='string'||!Number.isFinite(Date.parse(parsed.createdAt))||parsed.accessExpiresAt!==null&&!Number.isFinite(Date.parse(parsed.accessExpiresAt))||await sha256(jsonBytes(parsed.projection))!==parsed.contentHash)throw new SyncProtocolError('PROTOCOL_INVALID');
 function validate(p:PublicProjection,root=true){if(!p||p.format!=='scenario-projection'||p.formatVersion!=='1.0.0'||typeof p.title!=='string'||!Array.isArray(p.entities)||!Array.isArray(p.relations)||!Array.isArray(p.searchIndex)||!Array.isArray(p.calendars)||Object.keys(p).some(k=>!['format','formatVersion','title','mainStart','calendars','entities','relations','searchIndex','versions'].includes(k)))throw new SyncProtocolError('PROTOCOL_INVALID');const ids=new Set<string>();
  for(const e of p.entities){if(!e||!publicId.test(e.id)||ids.has(e.id)||!PROJECTION_FIELDS[e.kind]||e.status!=='confirmed'||typeof e.name!=='string'||!e.data||Object.keys(e).some(k=>!['id','kind','name','status','data'].includes(k)))throw new SyncProtocolError('PROTOCOL_INVALID');ids.add(e.id);const allowed=new Set([...Object.keys(PROJECTION_FIELDS[e.kind]!),...(e.kind==='attachment'?['mediaType','assetPath','contentHash','byteSize','bytesIncluded']:[])]);if(Object.keys(e.data).some(k=>!allowed.has(k)))throw new SyncProtocolError('PROTOCOL_INVALID');for(const [key,value]of Object.entries(e.data)){if(PROJECTION_FIELDS[e.kind]?.[key]?.type==='rich'){if(!Array.isArray(value)||value.some(raw=>{const b=raw as unknown as ProjectedBlock;return !b||Object.keys(b).some(k=>!['id','kind','text','ruby','links'].includes(k))||!publicId.test(b.id)||typeof b.text!=='string'||b.links?.some(l=>Object.keys(l).some(k=>!['start','end','targetId','blockId','lineId','sourceVersionId','targetStart','targetEnd'].includes(k)))||b.ruby?.some(r=>Object.keys(r).some(k=>!['start','end','text'].includes(k)));}))throw new SyncProtocolError('PROTOCOL_INVALID');}}}
  for(const r of p.relations)if(Object.keys(r).some(k=>!['id','fromId','toId','relationType','direction','evidenceIds','validity'].includes(k))||!publicId.test(r.id)||!ids.has(r.fromId)||!ids.has(r.toId)||!Array.isArray(r.evidenceIds)||r.evidenceIds.some(id=>!ids.has(id)))throw new SyncProtocolError('PROTOCOL_INVALID');
  if(p.searchIndex.some(e=>Object.keys(e).some(k=>!['entityId','kind','name','text','normalized'].includes(k))||!ids.has(e.entityId)||typeof e.text!=='string'||typeof e.name!=='string'))throw new SyncProtocolError('PROTOCOL_INVALID');if(!root&&p.versions?.length)throw new SyncProtocolError('PROTOCOL_INVALID');if((p.versions?.length??0)>128||new Set(p.versions?.map(v=>v.id)).size!==(p.versions?.length??0))throw new SyncProtocolError('PROTOCOL_INVALID');for(const v of p.versions??[]){if(Object.keys(v).some(k=>!['id','projection'].includes(k))||!publicId.test(v.id))throw new SyncProtocolError('PROTOCOL_INVALID');validate(v.projection,false);}
 }
 validate(parsed.projection);if(validatePublicPositions(parsed.projection).length)throw new SyncProtocolError('PROTOCOL_INVALID');return parsed;
}
export function projectedRichText(blocks:unknown){return (Array.isArray(blocks)?blocks:[]) .map(raw=>{const b=raw as unknown as ProjectedBlock;return {...b,links:b.links?.map(l=>({start:l.start,end:l.end,target:{entityId:l.targetId,...l.blockId?{blockId:l.blockId}:{},...l.lineId?{lineId:l.lineId}:{},...l.sourceVersionId?{sourceVersionId:l.sourceVersionId}:{},...l.targetStart!==undefined?{start:l.targetStart}:{},...l.targetEnd!==undefined?{end:l.targetEnd}:{}}}))};});}
